new='''/** Rows fetched per page while walking a project's content. */
const WALK_PAGE_SIZE = 100;

/**
 * Indexes a project only while it is live; otherwise makes sure it is absent.
 * Returns whether the document is now in the index.
 */
export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<boolean> {
  const current = await projectRepo.findProjectById(orgId, project.id);
  if (!current || project.archivedAt !== null || current.archivedAt !== null) {
    await removeFromIndex(orgId, "project", project.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\\n"),
    project.id,
  );
  return true;
}

/** Indexes an issue only while the issue and its project are both live. */
export async function indexIssue(orgId: OrgId, issue: Issue): Promise<boolean> {
  const current = await issueRepo.findIssueById(orgId, issue.id);
  const project = current
    ? await projectRepo.findProjectById(orgId, current.projectId)
    : null;
  if (
    !current ||
    !project ||
    issue.archivedAt !== null ||
    current.archivedAt !== null ||
    project.archivedAt !== null
  ) {
    await removeFromIndex(orgId, "issue", issue.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\\n"),
    issue.projectId,
  );
  return true;
}

/** Indexes a comment only while it, its issue and that issue's project are live. */
export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<boolean> {
  const current = await commentRepo.findCommentById(orgId, comment.id);
  const issue = current
    ? await issueRepo.findIssueById(orgId, current.issueId)
    : null;
  const project = issue
    ? await projectRepo.findProjectById(orgId, issue.projectId)
    : null;
  if (
    !current ||
    !issue ||
    !project ||
    comment.archivedAt !== null ||
    current.archivedAt !== null ||
    issue.archivedAt !== null ||
    project.archivedAt !== null
  ) {
    await removeFromIndex(orgId, "comment", comment.id);
    return false;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
  return true;
}

export async function removeFromIndex(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  await searchRepo.deleteSearchDocument(orgId, subjectKind, subjectId);
}

/** Calls `visit` for every comment of an issue, live or archived, page by page. */
async function forEachComment(
  orgId: OrgId,
  issueId: Issue["id"],
  visit: (comment: Comment) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId,
      includeArchived: true,
      limit: WALK_PAGE_SIZE,
      cursor,
    });
    for (const comment of page.items) await visit(comment);
    cursor = page.nextCursor;
  } while (cursor !== null);
}

/** Re-indexes a project's live issues and their live comments, page by page. */
async function reindexProjectContent(
  orgId: OrgId,
  projectId: Project["id"],
): Promise<void> {
  let cursor: string | null = null;
  do {
    const page = await issueRepo.listIssues({
      orgId,
      projectId,
      limit: WALK_PAGE_SIZE,
