new='''/**
 * Walks one tenant's projects, issues and comments, page by page, and
 * re-upserts every document the visibility rule allows. Scoped to a single org
 * on purpose: a full-fleet reindex is a sequence of these, so one slow tenant
 * cannot stall the rest.
 *
 * Archived rows are read too, but the index writers decide whether a row is
 * searchable (a project while live, an issue while it and its project are
 * live, a comment while it, its issue and the project are live). Afterwards
 * every entry of this org that the walk did not confirm — archived content,
 * deleted comments, rows that no longer exist — is swept out.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    // Documents to keep: confirmed searchable, or unknown because indexing failed.
    const keep = new Set<string>();
    const keyOf = (kind: string, id: string) => `${kind}:${id}`;

    let projectCursor: string | null = null;
    do {
      const projects = await projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor: projectCursor,
        includeArchived: true,
      });

      for (const project of projects.items) {
        try {
          if (await indexProject(orgId, project)) {
            keep.add(keyOf("project", project.id));
          }
          result.processed += 1;
        } catch (error) {
          keep.add(keyOf("project", project.id));
          result.failed += 1;
          logger.error("failed to index project", {
            projectId: project.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      projectCursor = projects.nextCursor;
    } while (projectCursor !== null);

    let issueCursor: string | null = null;
    do {
      const issues = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: issueCursor,
        includeArchived: true,
      });

      for (const issue of issues.items) {
        try {
          const indexed = await indexIssue(orgId, issue);
          if (indexed) keep.add(keyOf("issue", issue.id));
          result.processed += 1;
          if (!indexed) continue;

          let commentCursor: string | null = null;
          do {
            const comments = await commentRepo.listComments({
              orgId,
              issueId: issue.id,
              includeArchived: true,
              limit: PAGE_SIZE,
              cursor: commentCursor,
            });

            for (const comment of comments.items) {
              if (await indexComment(orgId, comment)) {
                keep.add(keyOf("comment", comment.id));
              }
              result.processed += 1;
            }
            commentCursor = comments.nextCursor;
          } while (commentCursor !== null);
        } catch (error) {
          keep.add(keyOf("issue", issue.id));
          result.failed += 1;
          logger.error("failed to index issue", {
            issueId: issue.id,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
      issueCursor = issues.nextCursor;
    } while (issueCursor !== null);

    for (const entry of await searchRepo.listIndexedSubjects(orgId)) {
      if (keep.has(keyOf(entry.subjectKind, entry.subjectId))) continue;
      await searchRepo.deleteSearchDocument(
        orgId,
        entry.subjectKind,
        entry.subjectId,
      );
    }
  });
}
